\begin{ex}%[9H4H1-3]
Cho tam giác ${ABC}$ vuông tại ${A}$.

a) biết $AC=2$, $\widehat{B} = 60^{\circ}$. Tính ${BC}$.

b) biết $AB=2$, $\widehat{B} = 30^{\circ}$. Tính ${BC}$.
\loigiai{
a) $\sin B= \dfrac{AC}{BC}$ hay $\sin{60^{\circ}}= \dfrac{2}{BC}$ nên ta có $BC=2:\sin{60^{\circ}}=\dfrac{4 \sqrt{3}}{3}$\\
b) $\cos B= \dfrac{AB}{BC}$ hay $\cos{60^{\circ}}= \dfrac{2}{BC}$ nên ta có $BC=2:\cos{60^{\circ}}=\dfrac{4 \sqrt{3}}{3}$
}\end{ex}

